const input = $('Validate Input').first().json;
const metaResponse = $('Fetch Meta Data').first().json;
const ghlResponse = $('Fetch GHL Data').first().json;

const metaData = metaResponse.body || metaResponse;
const ghlData = ghlResponse.body || ghlResponse;

const summary = metaData.data?.summary || {};
const pipeline = ghlData.pipeline || {};
const stages = pipeline.stages || [];

const closedStage = stages.find(s => s.name === 'Closed Won' || s.name === 'Closed');
const apptStage = stages.find(s => s.name === 'Appointment Set' || s.name === 'Appointments');
const appStage = stages.find(s => s.name === 'Application' || s.name === 'Applications');

return [{
  json: {
    clientId: input.clientId,
    clientName: input.clientName,
    brand: input.brand,
    month: input.month,
    metrics: {
      spend: summary.totalSpend || 0,
      reportedLeads: summary.reportedLeads || 0,
      trueLeads: summary.trueLeads || 0,
      trueCpl: summary.trueCpl || 0,
      cpm: summary.cpm || 0,
      frequency: summary.frequency || 0,
      doubleCount: summary.doubleCount || false
    },
    pipeline: {
      stages,
      closedDeals: closedStage?.count || 0,
      appointments: apptStage?.count || 0,
      applications: appStage?.count || 0
    }
  }
}];

