const context = $('Build Report Context').first().json;
const claudeResponse = $('Generate with Claude').first().json;
const body = claudeResponse.body || claudeResponse;

let sections;
try {
  const text = body.content?.[0]?.text || '{}';
  const cleaned = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  sections = JSON.parse(cleaned);
} catch (e) {
  sections = {
    whatWorked: 'Report generation in progress',
    whatChanged: '',
    actionsTaken: '',
    next30Days: '',
    summary: 'Report could not be fully generated. Raw data available in metrics.'
  };
}

return [{
  json: {
    success: true,
    reportId: 'report_' + context.clientId + '_' + Date.now(),
    clientId: context.clientId,
    clientName: context.clientName,
    brand: context.brand,
    month: context.month,
    sections,
    metrics: context.metrics,
    pipeline: context.pipeline
  }
}];
